// Apple's public root certificate — the trust anchor for App Store Server
// Notifications V2. Every notification is a JWS whose x5c header carries the full
// certificate chain; the Apple library verifies that chain terminates at THIS root
// before it will decode the payload. An attacker cannot forge a notification
// because they cannot produce a chain that Apple's root signs.
//
// Source: https://www.apple.com/certificateauthority/AppleRootCA-G3.cer (DER).
// Verified SHA-256 fingerprint:
//   63:34:3A:BF:B8:9A:6A:03:EB:B5:7E:9B:3F:5F:A7:BE:7C:4F:5C:75:6F:30:17:B3:A8:C4:88:C3:65:3E:91:79
// Self-signed root (subject == issuer, "Apple Root CA - G3", Apple Inc., US).
// This is a public certificate — safe to commit; it holds no secret.
//
// G3 is the anchor Apple uses for the App Store Server API and Server
// Notifications V2 JWS. If Apple ever rotates roots, add the new DER here — the
// verifier accepts an array, so multiple anchors coexist during a transition.

const APPLE_ROOT_CA_G3_DER_BASE64 =
  "";

/** DER-encoded Apple root certificates for the SignedDataVerifier trust store. */
export const APPLE_ROOT_CERTIFICATES: Buffer[] = [
  Buffer.from(APPLE_ROOT_CA_G3_DER_BASE64, "base64"),
];
